-- Three source-backed cases, with existing answer indices and effects preserved.
-- Only unassigned and unanswered cases are eligible; no historical scores change.
DO $guard$ BEGIN
IF (SELECT count(*) FROM public.event_cases WHERE case_key IN ('bank-budget-bridge','bank-budget-health','bank-budget-school') AND status='ready' AND NOT EXISTS (SELECT 1 FROM public.event_assignments a WHERE a.case_id=event_cases.id) AND NOT EXISTS (SELECT 1 FROM public.event_decisions d WHERE d.case_id=event_cases.id))<>3
THEN RAISE EXCEPTION 'One of the targeted cases is assigned or changed; do not alter live decisions'; END IF;
END $guard$;
UPDATE public.event_cases SET title='Обрушение путепровода в Вязьме: транспорт и безопасность', situation='8 апреля 2024 года в городе Вязьме Смоленской области обрушился Панинский путепровод. По официальному сообщению регионального управления МЧС, вызов поступил через систему 112 в 16:32. На путепроводе находились автомобили; один человек погиб, ещё пять человек были госпитализированы, включая ребёнка. Нарушение транспортной связности затронуло не только автомобильное движение: движение трёх пригородных поездов «Ласточка» было прервано, для пассажиров организовывали автобусное сообщение. На место направили восстановительные поезда и аварийно-спасательные подразделения.

При оценке последствий такого происшествия публичная власть должна различать экстренное спасение людей, обеспечение безопасного транспортного сообщения, обследование сохранившихся сооружений и последующее финансирование восстановительных работ. Эти задачи не решаются одной пресс-конференцией или обещанием немедленно построить новый мост. Необходимо установить владельца и балансодержателя конкретной дороги, компетенцию органов, ответственных за организацию движения, и безопасные направления объезда. Заключения специалистов должны лежать в основе решений об ограничении нагрузки на другие потенциально опасные сооружения, но сам факт аварии не доказывает непригодность любого соседнего моста.

Статья 30 Федерального закона № 257-ФЗ предусматривает правила временного ограничения или прекращения движения, а также меры по организации объездов и информированию пользователей дорог. Расходы на временные меры и восстановление должны иметь законный источник и документальное подтверждение. Учитывайте, что экстренные меры и долговременная реконструкция могут оформляться в разных процедурах. Какой порядок действий обеспечивает безопасность населения, непрерывность сообщения в доступной части транспортной сети и последующий контроль технического состояния и бюджетных расходов?', source_url='https://67.mchs.gov.ru/deyatelnost/press-centr/novosti/5250655', source_note='Фактическое событие: https://67.mchs.gov.ru/deyatelnost/press-centr/novosti/5250655. Правовое основание: Федеральный закон от 08.11.2007 № 257-ФЗ, статья 30 (временное ограничение движения, организация объездов и информирование пользователей дороги).' WHERE case_key='bank-budget-bridge' AND status='ready' AND NOT EXISTS (SELECT 1 FROM public.event_assignments a WHERE a.case_id=event_cases.id) AND NOT EXISTS (SELECT 1 FROM public.event_decisions d WHERE d.case_id=event_cases.id);
UPDATE public.event_cases SET title='Томск: доступность записи к детскому стоматологу', situation='6 ноября 2025 года прокуратура Томской области сообщила о результатах проверки детской стоматологической поликлиники № 2 города Томска. Поводом стали публикации о трудностях получения медицинской помощи детьми. Проверка установила, что запись на плановый приём была доступна через портал «Госуслуги», регистратуру и телефон, однако записаться заранее фактически не удавалось: свободное время открывалось только на следующий день. Кроме того, учреждению не хватало врачей-стоматологов. Прокуратура внесла представление в региональный департамент здравоохранения. По сообщению надзорного ведомства, после вмешательства запись стала доступна на две недели вперёд, а в поликлинику приняли двух врачей.

Речь идёт не только о количестве пациентов в очереди, но и о проверяемой доступности записи, обеспечении врачебными кадрами, прозрачности расписания и соблюдении права на медицинскую помощь. Одного заявления о переводе записи в электронный формат недостаточно, если у родителей по-прежнему нет реальной возможности выбрать доступное время. Перевод всех пациентов в другую поликлинику без согласованной мощности не устранит дефицит предложения и может затронуть права пациентов. Вместе с тем капитальные расходы на реконструкцию помещений не являются автоматически лучшим ответом на организационную проблему записи.

Статья 10 Федерального закона № 323-ФЗ связывает доступность медицинской помощи, в частности, с организацией её оказания и наличием необходимого количества медицинских работников. При повторении подобной ситуации профильный орган должен сопоставить кадровую нагрузку, структуру приёмов и ограничения рабочего времени, проверить фактическую доступность расписания для разных способов записи и определить измеримые показатели исправления. Какой вариант решения позволяет быстро восстановить доступ к приёму, не нарушая трудовые и медицинские требования и не заменяя доказанную потребность произвольными капитальными затратами?', source_url='https://epp.genproc.gov.ru/ru/proc_70/mass-media/news/main/e6347877/', source_note='Фактическое событие: https://epp.genproc.gov.ru/ru/proc_70/mass-media/news/main/e6347877/. Правовое основание: Федеральный закон от 21.11.2011 № 323-ФЗ, статья 10 (доступность и качество медицинской помощи, кадровое обеспечение).' WHERE case_key='bank-budget-health' AND status='ready' AND NOT EXISTS (SELECT 1 FROM public.event_assignments a WHERE a.case_id=event_cases.id) AND NOT EXISTS (SELECT 1 FROM public.event_decisions d WHERE d.case_id=event_cases.id);
UPDATE public.event_cases SET title='Самара: протечки кровли школы № 37', situation='24 сентября 2025 года прокуратура Железнодорожного района города Самары сообщила о завершении исполнения судебного решения по ремонту кровли школы № 37. Проверкой были выявлены дефекты потолков и стен, а также следы протечек, обусловленных ветхостью кровельного покрытия. Прокуратура указала, что такие нарушения создают небезопасные условия для здоровья учеников, и потребовала через суд обязать городской департамент образования профинансировать ремонт, а школу — организовать его проведение. Суд удовлетворил требования прокурора. В опубликованном сообщении отмечено, что решение исполнено и кровля отремонтирована.

Этот случай показывает необходимость различать полномочия учредителя, директора школы, органа местного самоуправления и подрядчика. Наличие дефектов не означает, что директор вправе единолично принять любые новые бюджетные обязательства; одновременно ожидание нового масштабного проекта не оправдывает продолжение эксплуатации опасных помещений. Первоначально требуется документально установить техническое состояние кровли и степень риска, определить безопасный порядок проведения занятий, уточнить объём необходимых работ, их финансирование, порядок закупки и контроля исполнения. Последовательность действий должна учитывать права учащихся и работников, а также возможность продолжать образование без пребывания в небезопасных помещениях.

Федеральный закон № 273-ФЗ возлагает на образовательную организацию обязанности по обеспечению безопасных условий обучения и охраны здоровья обучающихся. Контроль расходования бюджетных средств, техническая приёмка и документирование ремонта не отменяют первоначальную обязанность своевременно предупредить риск. Рассматривая альтернативные действия, отличайте аварийное устранение опасности от возможной последующей модернизации здания: это разные управленческие решения. Какой порядок действий одновременно защищает учащихся, позволяет установить законный источник финансирования и обеспечивает реальную проверку качества выполненных работ?', source_url='https://epp.genproc.gov.ru/ru/proc_63/mass-media/news/regional/e5982928/', source_note='Фактическое событие: https://epp.genproc.gov.ru/ru/proc_63/mass-media/news/regional/e5982928/. Правовое основание: Федеральный закон от 29.12.2012 № 273-ФЗ, статьи 28 и 41 (безопасные условия обучения и охрана здоровья обучающихся).' WHERE case_key='bank-budget-school' AND status='ready' AND NOT EXISTS (SELECT 1 FROM public.event_assignments a WHERE a.case_id=event_cases.id) AND NOT EXISTS (SELECT 1 FROM public.event_decisions d WHERE d.case_id=event_cases.id);
DO $check$ BEGIN
IF (SELECT count(*) FROM public.event_cases WHERE case_key IN ('bank-budget-bridge','bank-budget-health','bank-budget-school') AND source_url LIKE 'https://%')<>3 THEN RAISE EXCEPTION 'Source-backed case update incomplete'; END IF;
END $check$;